-- Flashcard top-up: Biology|Edexcel|gcse — brings each topic up to 30 cards.
-- Generated by scripts/build-flashcard-topup.js from flashcards/topup/src/biology-edexcel-gcse.txt
-- Safe to re-run: skips fronts already present and never takes a topic past 30.
WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Define magnification.', 'How many times bigger an image is than the real size of the object.', 1),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Define resolution.', 'The smallest distance between two points that can still be seen as separate; higher resolution means more detail.', 2),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Why do electron microscopes have a higher resolution than light microscopes?', 'Electrons have a much shorter wavelength than visible light, so smaller structures (e.g. ribosomes, organelle detail) can be distinguished.', 3),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'State the magnification equation.', 'Magnification = image size ÷ real size (both in the same units).', 4),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Calculate the magnification if image size is 12 mm and real size is 0.04 mm.', 'Magnification = image ÷ real = 12 ÷ 0.04 = ×300.', 5),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'A cell is 25 µm long. Its image is 50 mm. What is the magnification?', 'Convert: 50 mm = 50 000 µm. Magnification = 50 000 ÷ 25 = ×2000.', 6),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'How many micrometres are in 1 mm, and nanometres in 1 µm?', '1 mm = 1000 µm; 1 µm = 1000 nm.', 7),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Write 0.000 05 m in standard form and in micrometres.', '5 × 10⁻⁵ m = 50 µm.', 8),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'How is total magnification of a light microscope calculated?', 'Eyepiece lens magnification × objective lens magnification (e.g. ×10 × ×40 = ×400).', 9),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Core practical: how do you prepare an onion cell slide?', 'Peel thin epidermis, lay flat on slide in a drop of water, add iodine stain, lower coverslip at an angle with a mounting needle to avoid air bubbles.', 10),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Core practical: how should you focus a light microscope?', 'Start with lowest-power objective, raise stage close using coarse focus while watching from the side, then focus moving away; refine with fine focus, then switch to higher power.', 11),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'What are the rules for a scientific drawing of cells?', 'Sharp pencil, clear continuous lines, no shading, label lines with a ruler not crossing, title and magnification stated.', 12),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Name the subcellular structures found in animal cells.', 'Nucleus, cytoplasm, cell membrane, mitochondria and ribosomes.', 13),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Which three extra structures do plant cells have?', 'Cellulose cell wall, chloroplasts and a permanent vacuole filled with cell sap.', 14),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'What is the function of the mitochondria?', 'Site of aerobic respiration, releasing energy for the cell.', 15),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'What is the function of ribosomes?', 'Site of protein synthesis.', 16),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Name the structures found in a bacterial cell.', 'Cell wall, cell membrane, cytoplasm, ribosomes, chromosomal DNA (single loop), plasmid DNA and flagella.', 17),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Difference between prokaryotic and eukaryotic cells?', 'Prokaryotes (bacteria) lack a nucleus and membrane-bound organelles, are much smaller and have a loop of DNA plus plasmids; eukaryotes have a nucleus.', 18),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'How is a sperm cell adapted?', 'Acrosome with digestive enzymes to penetrate egg, haploid nucleus, many mitochondria for energy, tail (flagellum) to swim.', 19),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'How is an egg cell adapted?', 'Nutrients in cytoplasm, haploid nucleus, cell membrane changes after fertilisation so only one sperm enters.', 20),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'How are ciliated epithelial cells adapted?', 'Cilia on surface beat to move mucus (and trapped particles) up the airways or eggs along the oviduct.', 21),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Explain the lock and key model.', 'The substrate has a complementary shape to the enzyme''s active site, so it fits to form an enzyme-substrate complex; products are then released.', 22),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'What does denatured mean for an enzyme?', 'High temperature or extreme pH changes the shape of the active site so the substrate no longer fits; this is irreversible.', 23),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Common exam trap: do enzymes die at high temperatures?', 'No. Enzymes are not alive; they denature because the active site changes shape.', 24),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Core practical: how is the effect of pH on amylase measured?', 'Mix amylase, starch and buffer at set pH in water bath; every 10 s sample onto iodine in spotting tile; record time until iodine stays orange-brown.', 25),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Starch was fully broken down in 40 s. Calculate the rate.', 'Rate = 1000 ÷ time = 1000 ÷ 40 = 25 s⁻¹ (or 1/40 = 0.025 s⁻¹).', 26),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Name the enzymes that break down carbohydrates, proteins and lipids.', 'Carbohydrases (e.g. amylase) to simple sugars; proteases to amino acids; lipases to fatty acids and glycerol.', 27),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Food tests: what are the tests for starch, reducing sugar, protein and lipid?', '(Biology only) Iodine turns blue-black; Benedict''s heated turns brick-red; biuret turns lilac/purple; ethanol emulsion turns cloudy white.', 28),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Define diffusion, osmosis and active transport.', 'Diffusion: net movement of particles high to low concentration. Osmosis: net movement of water across a partially permeable membrane from dilute to concentrated solution. Active transport: low to high, needs energy from respiration.', 29),
  ('Biology', 'Edexcel', 'gcse', '1', 'Key Concepts in Biology', 'Core practical: potato chip mass rose from 2.0 g to 2.3 g in water. Percentage change?', '(2.3 − 2.0) ÷ 2.0 × 100 = +15%. Water entered by osmosis because the solution was more dilute than the cell contents.', 30),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'What is the cell cycle?', 'Interphase (cell grows, organelles and DNA replicated), mitosis (chromosomes separate), cytokinesis (cytoplasm and membrane divide).', 1),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'State the stages of mitosis in order.', 'Prophase, metaphase, anaphase, telophase, then cytokinesis.', 2),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'What happens in prophase?', 'Chromosomes condense and become visible, nuclear membrane breaks down.', 3),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'What happens in metaphase?', 'Chromosomes line up along the middle (equator) of the cell.', 4),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'What happens in anaphase?', 'Spindle fibres pull chromatids of each chromosome to opposite poles of the cell.', 5),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'What happens in telophase and cytokinesis?', 'Nuclear membranes form around each set of chromosomes; the cytoplasm and cell membrane then divide, forming two cells.', 6),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'What are the products of mitosis?', 'Two genetically identical diploid daughter cells.', 7),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'Give three uses of mitosis.', 'Growth, repair of damaged tissue and asexual reproduction.', 8),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'How does cancer form?', 'Changes (mutations) in cells lead to uncontrolled cell division by mitosis, forming a tumour.', 9),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'Define differentiation.', 'The process by which cells become specialised for a particular function.', 10),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'How do plants grow?', 'Cell division by mitosis in meristems (shoot and root tips), cell elongation, and cell differentiation.', 11),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'How do animals grow?', 'Cell division and differentiation; most animal cells differentiate early and lose the ability to divide.', 12),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'What are percentile charts used for?', 'Monitoring growth of babies/children (e.g. mass, head circumference) against the population to spot problems early.', 13),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'A baby is on the 75th percentile for mass. What does that mean?', '75% of babies of the same age weigh less than this baby, and 25% weigh more.', 14),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'Calculate percentage growth if a seedling grows from 4.0 cm to 5.0 cm.', '(5.0 − 4.0) ÷ 4.0 × 100 = 25% increase.', 15),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'What is a stem cell?', 'An undifferentiated cell that can divide to produce more stem cells and can differentiate into specialised cells.', 16),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'Compare embryonic and adult stem cells.', 'Embryonic can differentiate into any cell type; adult (e.g. bone marrow) can only form a limited range of cells.', 17),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'Where are plant stem cells found and what can they do?', 'In meristems; they can differentiate into any type of plant cell throughout the plant''s life.', 18),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'Give a benefit and two risks of using stem cells in medicine.', 'Benefit: replace damaged cells (e.g. Parkinson''s, spinal injury). Risks: rejection by immune system, could become cancerous or carry viruses; embryonic use raises ethical issues.', 19),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'Name the parts of the brain and their functions.', '(Biology only) Cerebrum: thought, memory, language; cerebellum: balance and muscle coordination; medulla oblongata: unconscious actions like heart rate and breathing.', 20),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'How can brain damage be investigated?', '(Biology only) CT scans (X-rays) show structure; PET scans (radioactive tracer) show active areas; treatment is difficult as the brain is complex and delicate.', 21),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'What makes up the central nervous system?', 'The brain and spinal cord.', 22),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'Describe the structure of a sensory neurone.', 'Long dendron carrying impulses from receptor to cell body, short axon to the CNS; myelin sheath and dendrites.', 23),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'What is the function of the myelin sheath?', 'Insulates the axon so impulses jump between gaps, speeding up transmission.', 24),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'Describe how an impulse crosses a synapse.', 'Impulse arrives, neurotransmitter released, diffuses across the gap, binds to receptors on next neurone, triggering a new impulse.', 25),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'State the path of a reflex arc.', 'Stimulus, receptor, sensory neurone, relay neurone (in spinal cord), motor neurone, effector, response.', 26),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'Why are reflexes important?', 'They are rapid and automatic, protecting the body from harm; they bypass the conscious brain.', 27),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'How does the eye focus on a near object?', '(Biology only) Ciliary muscles contract, suspensory ligaments slacken, lens becomes fatter (more convex) and refracts light more.', 28),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'What causes short-sightedness and how is it corrected?', '(Biology only) Light focused in front of the retina (eyeball too long or lens too thick); corrected with a concave (diverging) lens.', 29),
  ('Biology', 'Edexcel', 'gcse', '2', 'Cells and Control', 'What are rods and cones?', '(Biology only) Retina receptor cells: rods detect dim light (black and white); cones detect colour in bright light. Colour blindness involves faulty cones.', 30),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'Compare sexual and asexual reproduction.', 'Sexual: two parents, gametes fuse, variation in offspring. Asexual: one parent, mitosis, genetically identical clones, quicker.', 1),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'Give one advantage of sexual reproduction.', '(Biology only) Produces variation, so a population is more likely to survive environmental change or disease.', 2),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'Give one advantage of asexual reproduction.', '(Biology only) Only one parent needed, faster, and many offspring produced when conditions are favourable.', 3),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'What are gametes?', 'Sex cells (sperm and egg in animals; pollen and egg in plants) with half the normal number of chromosomes (haploid).', 4),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'What does meiosis produce?', 'Four genetically different haploid gametes from one diploid cell, after two divisions.', 5),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'Why is meiosis needed for sexual reproduction?', 'Halving chromosome number means the diploid number (46 in humans) is restored at fertilisation.', 6),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'Describe the structure of DNA.', 'A polymer made of two strands of nucleotides coiled into a double helix, held together by hydrogen bonds between complementary bases.', 7),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'What is a nucleotide made of?', 'A sugar (deoxyribose), a phosphate group and one of four bases (A, T, C, G).', 8),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'State the complementary base pairs.', 'Adenine pairs with thymine (A–T); cytosine pairs with guanine (C–G).', 9),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'DNA has 30% adenine. What percentage is guanine?', 'T = 30%, so A + T = 60%; C + G = 40%, so G = 20%.', 10),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'Practical: how do you extract DNA from fruit?', 'Mash fruit with detergent (breaks membranes) and salt (clumps DNA), filter, then pour ice-cold ethanol down the side; DNA precipitates as white strands.', 11),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'Define gene and genome.', 'Gene: a section of DNA coding for a specific protein. Genome: the entire genetic material of an organism.', 12),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'How does a gene code for a protein?', 'A sequence of three bases (triplet) codes for one amino acid; the order of bases determines the order of amino acids.', 13),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'Describe transcription.', '(Biology only, Higher) RNA polymerase binds to non-coding DNA before the gene; DNA unzips; complementary mRNA is made from the template strand and leaves the nucleus.', 14),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'Describe translation.', '(Biology only, Higher) mRNA attaches to a ribosome; tRNA molecules bring specific amino acids, their anticodons pairing with mRNA codons; amino acids join to form a polypeptide.', 15),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'How can a mutation in non-coding DNA affect a phenotype?', '(Biology only, Higher) It can affect where RNA polymerase binds, changing how much protein (mRNA) is made.', 16),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'What did Mendel discover?', '(Biology only) Using pea plants he showed inherited characteristics are passed on as separate units (now genes), with some dominant and some recessive.', 17),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'Define allele, dominant and recessive.', 'Allele: a different version of a gene. Dominant: expressed if one copy present. Recessive: only expressed if two copies present.', 18),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'Define genotype and phenotype.', 'Genotype: the alleles an organism has (e.g. Bb). Phenotype: the observable characteristic (e.g. brown eyes).', 19),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'Define homozygous and heterozygous.', 'Homozygous: two identical alleles (BB or bb). Heterozygous: two different alleles (Bb).', 20),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'Two heterozygous parents (Ff) for cystic fibrosis have a child. Probability child has CF?', 'Punnett square gives FF, Ff, Ff, ff: 1 in 4, 25% (ratio 3:1 unaffected to affected).', 21),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'How is sex determined in humans?', 'Females are XX, males XY; the father''s sperm carries X or Y, giving a 50% chance of each sex.', 22),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'How are ABO blood groups inherited?', '(Biology only) Multiple alleles: IA and IB are codominant, IO is recessive; IAIB gives group AB, IOIO gives group O.', 23),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'Why are sex-linked disorders more common in males?', '(Biology only) The allele is recessive on the X chromosome; males have only one X, so one faulty allele causes the disorder (e.g. colour blindness, haemophilia).', 24),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'What is a family pedigree used for?', 'Tracing how a characteristic is inherited through generations to work out genotypes and probabilities.', 25),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'What causes variation?', 'Genetic variation (alleles inherited, mutation) and environmental variation (e.g. diet, climate); most characteristics are influenced by both.', 26),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'What is a mutation?', 'A change in the DNA base sequence; most have no effect, some affect the phenotype a little, rarely significantly.', 27),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'What was the Human Genome Project?', 'An international project that mapped the full sequence of bases in human DNA, completed in 2003.', 28),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'Give uses of knowing the human genome.', 'Identify genes linked to disease, personalised medicine tailored to a person''s alleles, better understanding of inherited disorders and human migration.', 29),
  ('Biology', 'Edexcel', 'gcse', '3', 'Genetics', 'Exam trap: are most characteristics controlled by one gene?', 'No. Most are controlled by many genes interacting with the environment; single-gene examples include cystic fibrosis and polydactyly.', 30),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'Who proposed the theory of evolution by natural selection?', 'Charles Darwin; Alfred Russel Wallace independently came to similar conclusions.', 1),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'Describe evolution by natural selection.', 'Variation from mutation; competition for resources; individuals with advantageous alleles survive and reproduce; they pass on alleles, so the allele becomes more frequent over generations.', 2),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'Explain how antibiotic resistance develops in bacteria.', 'A mutation gives resistance; antibiotic kills non-resistant bacteria; resistant ones survive and reproduce rapidly, passing on the allele; resistant population grows.', 3),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'Why does antibiotic resistance provide evidence for evolution?', 'Bacteria reproduce rapidly, so the change in allele frequency through natural selection can be observed over a short time.', 4),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'How can antibiotic resistance be reduced?', 'Only prescribe antibiotics when needed (not for viruses), complete the course, and limit use in farming.', 5),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'What is speciation?', 'Formation of a new species when populations become so different they can no longer interbreed to produce fertile offspring.', 6),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'What does the hominid fossil Ardi show?', 'Ardipithecus ramidus, 4.4 million years old: mix of ape and human features, grasping big toe for climbing, but walked upright; small brain (~350 cm³).', 7),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'What does the fossil Lucy show?', 'Australopithecus afarensis, 3.2 million years old: walked upright more efficiently than Ardi, arched feet, brain about 400 cm³.', 8),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'What did Leakey''s discoveries show?', 'Turkana Boy (Homo erectus, 1.6 million years): more human-like, taller, larger brain (~880 cm³); Leakey also found Homo habilis fossils and stone tools.', 9),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'How do stone tools show human evolution?', 'Tools became more complex over time (e.g. simple pebble tools to shaped hand axes), suggesting brain size and skill increased; dated by stratigraphy.', 10),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'How can stone tools and fossils be dated?', 'By the rock layer they are found in (deeper layers are older) and by carbon-14 dating of nearby material.', 11),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'What is the pentadactyl limb?', 'A five-digit limb structure found in many vertebrates (mammals, birds, reptiles, amphibians), evidence they share a common ancestor.', 12),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'Why is the fossil record incomplete?', 'Soft tissue decays, conditions for fossilisation are rare, and many fossils are destroyed by geological activity or not yet found.', 13),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'What is the three-domain system?', 'Carl Woese''s classification based on RNA/DNA sequences: Archaea, Bacteria and Eukarya.', 14),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'List the classification levels in order.', 'Kingdom, phylum, class, order, family, genus, species.', 15),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'Why has classification changed over time?', 'Genetic analysis (DNA sequencing) revealed relationships that physical features could not, e.g. archaea differ from bacteria.', 16),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'What are the five kingdoms?', 'Animals, plants, fungi, protists and prokaryotes.', 17),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'Define selective breeding.', 'Humans choosing parents with desired characteristics to breed together, over many generations, to produce offspring with those characteristics.', 18),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'Give two risks of selective breeding.', 'Reduced gene pool (inbreeding) increases risk of inherited disorders, and less variation makes populations vulnerable to new diseases.', 19),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'What is tissue culture?', '(Biology only) Growing new plants from a small piece of tissue on sterile nutrient medium with hormones; produces many identical clones quickly.', 20),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'What is genetic engineering?', 'Changing an organism''s genome by inserting a gene from another organism to give a desired characteristic.', 21),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'Describe the stages of genetic engineering.', '(Higher) Restriction enzymes cut out gene leaving sticky ends; same enzyme cuts plasmid vector; ligase joins gene into plasmid; plasmid inserted into host cell.', 22),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'What is a vector in genetic engineering?', 'Something used to carry the gene into the host cell, e.g. a bacterial plasmid or virus.', 23),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'Give an example of genetic engineering in medicine.', 'Bacteria engineered with the human insulin gene produce insulin for people with diabetes.', 24),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'How are crops engineered to resist insects?', '(Biology only) The Bt gene from a bacterium is inserted so the plants produce a toxin that kills insect larvae, reducing crop damage and pesticide use.', 25),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'Give benefits and risks of GM crops.', 'Benefits: higher yields, pest/herbicide resistance, extra nutrients (e.g. Golden Rice). Risks: genes transfer to wild plants, harm to insects, long-term effects unknown, seed cost.', 26),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'How do fertilisers and biological control increase food production?', '(Biology only) Fertilisers add minerals (nitrates) for growth; biological control uses a predator or parasite to reduce pests without chemicals.', 27),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'Give a risk of biological control.', '(Biology only) The introduced species may become a pest itself or harm native species.', 28),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'Exam trap: does an individual organism evolve during its lifetime?', 'No. Populations evolve over generations; individuals do not change their alleles in response to the environment.', 29),
  ('Biology', 'Edexcel', 'gcse', '4', 'Natural Selection & Genetic Modification', 'Define species.', 'A group of similar organisms that can interbreed to produce fertile offspring.', 30),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'How does the WHO define health?', 'A state of complete physical, mental and social well-being, not merely the absence of disease.', 1),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Define communicable and non-communicable disease.', 'Communicable: caused by a pathogen and can spread between individuals. Non-communicable: cannot spread, e.g. heart disease, cancer.', 2),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'How can one disease increase the risk of another?', 'e.g. HIV weakens the immune system, increasing the chance of TB; malnutrition or infection can make someone more susceptible.', 3),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Name the four types of pathogen with an example of each.', 'Bacteria (cholera, TB), viruses (HIV, Ebola), fungi (Chalara ash dieback), protists (malaria).', 4),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Describe the lytic cycle of a virus.', '(Biology only) Virus attaches and injects genetic material; host replicates viral material and proteins; new viruses assemble; cell bursts (lyses) releasing them.', 5),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'How does the lysogenic cycle differ?', '(Biology only) Viral DNA inserts into host genome and is copied each division without harm until triggered to enter the lytic cycle.', 6),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Cholera: cause, spread, symptoms, prevention.', 'Bacterium Vibrio cholerae; spread by contaminated water; causes diarrhoea and dehydration; prevented by clean water supplies.', 7),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Tuberculosis: cause, spread, prevention.', 'Bacterium Mycobacterium tuberculosis; airborne droplets; lung damage; reduced by isolating patients, good ventilation, completing antibiotic course, BCG vaccine.', 8),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Chalara ash dieback: cause, spread, prevention.', 'Fungus; spores carried by wind; leaf loss and bark lesions in ash trees; controlled by removing infected trees and restricting import of young trees.', 9),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Malaria: cause, spread, prevention.', 'Protist (Plasmodium) carried by mosquito vectors; recurring fever; prevented by nets, insecticides, removing standing water, antimalarial drugs.', 10),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'HIV: cause, spread, prevention.', 'Virus spread by bodily fluids (sex, sharing needles); destroys white blood cells leading to AIDS; prevented by condoms, not sharing needles; antiretroviral drugs slow it.', 11),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Stomach ulcers: cause, spread, treatment.', 'Bacterium Helicobacter pylori; spread by oral transmission (contaminated food/water); stomach pain; treated with antibiotics, reduced by clean water and hygiene.', 12),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Ebola: cause, spread, prevention.', 'Virus spread via bodily fluids; haemorrhagic fever; controlled by isolating patients, wearing protective clothing, safe burial.', 13),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Name two sexually transmitted infections and how to reduce their spread.', 'Chlamydia (bacterium) and HIV (virus); use condoms, screening and treatment, and not sharing needles for HIV.', 14),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Name the human body''s physical and chemical barriers to infection.', 'Skin, mucus and cilia in airways; lysozyme in tears; hydrochloric acid in the stomach.', 15),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'How do plants defend against pathogens?', '(Biology only) Physical: waxy cuticle, cellulose cell walls. Chemical: antiseptics and antimicrobial substances; some produce poisons to deter herbivores.', 16),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'How are plant diseases identified?', '(Biology only) Observing symptoms, distribution analysis, identifying pathogens in a lab, and testing kits using monoclonal antibodies.', 17),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Describe the specific immune response.', 'Lymphocytes with complementary antibodies to a pathogen''s antigens divide; plasma cells secrete antibodies; antibodies bind antigens, destroying pathogens; memory lymphocytes remain.', 18),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Explain how vaccination works.', 'Inactive or dead pathogen (antigens) injected; lymphocytes produce antibodies and memory cells; on re-infection a faster, larger secondary response destroys the pathogen.', 19),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'What is herd immunity?', 'When a large proportion of a population is vaccinated, the pathogen is less likely to spread, protecting unvaccinated people.', 20),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'How are monoclonal antibodies produced?', '(Biology only, Higher) Mouse lymphocytes making a specific antibody are fused with tumour cells to form hybridomas that divide and make identical antibodies.', 21),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Give uses of monoclonal antibodies.', '(Biology only, Higher) Pregnancy tests (detect hCG), locating blood clots or cancer cells, and delivering drugs to cancer cells.', 22),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'How do antibiotics work, and why can''t they treat viral infections?', 'They kill bacteria or stop their growth by damaging bacterial cells; viruses live inside host cells, so antibiotics cannot reach them without harming body cells.', 23),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Core practical: how do you test the effect of antiseptics on bacteria?', '(Biology only) Spread bacteria on agar plate aseptically, add discs soaked in antiseptics/antibiotics, incubate at 25°C, measure clear zones of inhibition.', 24),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Clear zone diameter is 14 mm. Calculate its area.', '(Biology only) r = 7 mm; area = πr² = 3.14 × 7² ≈ 154 mm².', 25),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Why are cultures incubated at no more than 25°C in schools?', '(Biology only) Reduces the chance of growing harmful human pathogens that thrive at 37°C.', 26),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Describe the stages of drug development.', 'Discovery; preclinical testing on cells, tissues and live animals; clinical trials on healthy volunteers (low dose for safety) then patients (efficacy, optimum dose).', 27),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'What is a double-blind trial?', 'Neither patients nor doctors know who receives the drug or placebo, preventing bias.', 28),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Give lifestyle risk factors for cardiovascular disease and treatments.', 'Smoking, poor diet, obesity, lack of exercise. Treatments: lifestyle change, statins/antihypertensives, stents, bypass surgery or heart transplant.', 29),
  ('Biology', 'Edexcel', 'gcse', '5', 'Health, Disease & Development of Medicines', 'Calculate waist:hip ratio for waist 90 cm and hip 100 cm.', '90 ÷ 100 = 0.9; a high ratio (abdominal obesity) increases cardiovascular disease risk.', 30),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'State the word equation for photosynthesis.', 'Carbon dioxide + water → glucose + oxygen (using light energy absorbed by chlorophyll).', 1),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'State the balanced symbol equation for photosynthesis.', '6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂.', 2),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'Why is photosynthesis an endothermic reaction?', 'Energy is transferred from the environment (light) to the chloroplasts.', 3),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'Why are plants described as producers?', 'They make biomass (glucose) by photosynthesis, which is the source of energy for food chains.', 4),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'Name the factors that limit the rate of photosynthesis.', 'Light intensity, carbon dioxide concentration and temperature.', 5),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'Explain the shape of a rate vs light intensity graph.', 'Rate rises as light increases, then plateaus because another factor (CO₂ or temperature) becomes limiting.', 6),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'Why does photosynthesis rate fall at high temperatures?', 'Enzymes involved are denatured, so the rate drops sharply.', 7),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'State the inverse square law for light intensity.', '(Higher) Light intensity ∝ 1 ÷ distance²; doubling the distance reduces intensity to a quarter.', 8),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'A lamp moves from 10 cm to 20 cm. By how much does light intensity change?', '(Higher) Distance doubles, so intensity becomes 1/2² = 1/4 of the original.', 9),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'Core practical: how is the effect of light intensity on photosynthesis investigated?', 'Pondweed in sodium hydrogencarbonate solution; lamp at set distances; count oxygen bubbles or measure gas volume per minute.', 10),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'Core practical: name the variables in the pondweed investigation.', 'Independent: distance from lamp (light intensity). Dependent: bubbles/gas per minute. Control: CO₂ (hydrogencarbonate), temperature, same pondweed, acclimatisation time.', 11),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'Why is a beaker of water placed between lamp and pondweed?', 'Acts as a heat shield so temperature stays constant and only light intensity varies.', 12),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'How do farmers use limiting factors in greenhouses?', 'Artificial lighting, paraffin heaters (raise temperature and CO₂) to increase yield; must balance extra cost against extra profit.', 13),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'Give five uses of glucose in plants.', 'Respiration, starch for storage, cellulose for cell walls, proteins (with nitrates), and lipids/oils for storage in seeds.', 14),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'How are root hair cells adapted?', 'Long projections give large surface area for absorbing water by osmosis and mineral ions by active transport; many mitochondria.', 15),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'Why do root hair cells need active transport?', 'Mineral ions are more concentrated inside root cells than in soil, so they must move against the concentration gradient using energy.', 16),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'Describe the structure of xylem.', 'Dead cells joined end to end with no end walls, forming hollow tubes strengthened by lignin; carry water and minerals upward.', 17),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'Describe the structure of phloem.', 'Living sieve tube cells with sieve plates (perforated end walls) and companion cells that provide energy; transport sucrose.', 18),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'What is translocation?', 'Movement of sucrose through phloem from sources (leaves) to sinks (roots, growing tissues, storage organs) in both directions, needing energy.', 19),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'What is transpiration?', 'Loss of water vapour from leaves by evaporation and diffusion out through stomata, pulling water up the xylem.', 20),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'How do guard cells control stomata?', 'When turgid, guard cells curve, opening the stoma; when flaccid, they close it, reducing water loss.', 21),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'Explain how leaves are adapted for photosynthesis and gas exchange.', 'Large flat surface, thin for short diffusion distance, palisade cells with many chloroplasts, air spaces in spongy mesophyll, stomata for CO₂ entry.', 22),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'How does temperature affect transpiration rate?', 'Higher temperature increases evaporation and diffusion of water vapour, increasing transpiration rate.', 23),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'How do humidity and wind speed affect transpiration?', 'High humidity reduces the concentration gradient so rate falls; wind removes water vapour near leaves, increasing rate.', 24),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'How is transpiration rate measured?', 'Using a potometer: record distance the air bubble moves in a capillary tube over time; rate = water uptake ÷ time.', 25),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'An air bubble moves 30 mm in 5 minutes. What is the rate of water uptake?', '30 ÷ 5 = 6 mm per minute.', 26),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'How do auxins cause phototropism?', '(Biology only) Auxin moves to the shaded side of the shoot, causing cells there to elongate more, so the shoot bends towards light.', 27),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'How do roots respond to gravity?', '(Biology only) Auxin collects on the lower side and inhibits cell elongation in roots, so the root bends downwards (positive gravitropism).', 28),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'Give commercial uses of plant hormones.', '(Biology only) Auxins: weedkillers, rooting powder. Gibberellins: seed germination, fruit size, flowering. Ethene: ripening fruit.', 29),
  ('Biology', 'Edexcel', 'gcse', '6', 'Plant Structures and Their Functions', 'How are plants adapted to dry conditions?', '(Biology only) Thick waxy cuticle, fewer or sunken stomata, small or spiny leaves, extensive roots, water storage tissue.', 30),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'What is a hormone?', 'A chemical messenger secreted by an endocrine gland into the blood, carried to a target organ where it has an effect.', 1),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'Compare nervous and hormonal responses.', 'Nervous: electrical impulses, very fast, short-lived, precise. Hormonal: chemicals in blood, slower, longer lasting, more widespread.', 2),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'Name the hormones made by the pituitary, thyroid and adrenal glands.', 'Pituitary: FSH, LH, TSH, ADH, growth hormone. Thyroid: thyroxine. Adrenal: adrenaline.', 3),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'Name the hormones made by the pancreas, ovaries and testes.', 'Pancreas: insulin and glucagon. Ovaries: oestrogen and progesterone. Testes: testosterone.', 4),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'What are the effects of adrenaline?', '(Higher) Increases heart rate and blood pressure, more blood to muscles, liver converts glycogen to glucose; prepares the body for fight or flight.', 5),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'How does negative feedback control thyroxine?', '(Higher) Low thyroxine triggers TSH release from the pituitary, stimulating thyroid to release thyroxine; high levels inhibit TSH release.', 6),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'What is the role of thyroxine?', '(Higher) Regulates the body''s metabolic rate.', 7),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'What are the stages of the menstrual cycle?', 'Days 1–4 menstruation; uterus lining rebuilds; ovulation about day 14; lining maintained; if no fertilisation, lining breaks down.', 8),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'What do oestrogen and progesterone do in the menstrual cycle?', 'Oestrogen builds the uterus lining (and inhibits FSH); progesterone maintains the lining and inhibits FSH and LH.', 9),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'How do FSH and LH control the menstrual cycle?', '(Higher) FSH causes egg to mature in a follicle and stimulates oestrogen; LH surge triggers ovulation and corpus luteum forms, which releases progesterone.', 10),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'How does the combined pill work?', 'Oestrogen and progesterone inhibit FSH and LH, so eggs do not mature or get released.', 11),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'Compare hormonal and barrier contraception.', 'Hormonal (pill, implant): more effective but side effects, no STI protection. Barrier (condoms): no hormones, protect against STIs, less reliable if misused.', 12),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'How does clomifene therapy treat infertility?', '(Higher) It increases FSH and LH release, stimulating egg maturation and ovulation.', 13),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'Describe IVF.', '(Higher) FSH and LH given to mature several eggs; eggs collected and fertilised by sperm in a lab; embryos grown then one or two implanted in the uterus.', 14),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'Define homeostasis.', 'Maintaining a constant internal environment (e.g. temperature, blood glucose, water) despite external changes.', 15),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'What happens when blood glucose concentration is too high?', 'Pancreas releases insulin; liver and muscle cells take up glucose and convert it to glycogen; glucose level falls.', 16),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'What happens when blood glucose concentration is too low?', '(Higher) Pancreas releases glucagon; liver converts glycogen back to glucose, releasing it into the blood.', 17),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'Exam trap: glycogen, glucagon or glucose?', 'Glucose is the sugar; glycogen is the storage carbohydrate; glucagon is the hormone that converts glycogen to glucose.', 18),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'Compare type 1 and type 2 diabetes.', 'Type 1: pancreas makes no insulin, treated with insulin injections. Type 2: cells stop responding to insulin, controlled by diet, exercise and drugs; linked to obesity.', 19),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'Calculate BMI for 95 kg and 1.80 m.', 'BMI = 95 ÷ 1.80² = 95 ÷ 3.24 ≈ 29.3 kg/m², overweight (obese is 30 or above).', 20),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'How does the body respond when too hot?', '(Biology only) Sweating (evaporation cools skin), vasodilation of skin arterioles so more heat lost by radiation, hairs lie flat.', 21),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'How does the body respond when too cold?', '(Biology only) Shivering (respiration releases heat), vasoconstriction reduces blood to skin, hairs raised to trap air, sweating stops.', 22),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'Where is body temperature monitored?', '(Biology only) Thermoregulatory centre in the hypothalamus detects blood temperature; skin receptors also send impulses.', 23),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'Describe the structure of a nephron.', '(Biology only) Bowman''s capsule (glomerulus), proximal convoluted tubule, loop of Henle, distal convoluted tubule, collecting duct.', 24),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'What happens during ultrafiltration and selective reabsorption?', '(Biology only) High pressure forces small molecules from glomerulus into Bowman''s capsule; all glucose and needed ions and water are reabsorbed in the tubule.', 25),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'How does ADH control water content of blood?', '(Biology only) When blood is too concentrated, pituitary releases more ADH, making collecting ducts more permeable so more water is reabsorbed; urine is concentrated.', 26),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'How is urea formed?', '(Biology only) Excess amino acids are deaminated in the liver, forming ammonia, which is converted into urea and excreted by the kidneys.', 27),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'Compare dialysis and kidney transplant.', '(Biology only) Dialysis: regular, time-consuming, dialysis fluid allows diffusion of urea out. Transplant: long-term, but risk of rejection, needs immunosuppressants and a donor.', 28),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'How does testosterone affect males at puberty?', 'Stimulates sperm production and secondary sexual characteristics such as facial hair and deeper voice.', 29),
  ('Biology', 'Edexcel', 'gcse', '7', 'Animal Coordination, Control & Homeostasis', 'Why must a hormone affect only certain organs?', 'Only target cells have specific receptors complementary to the hormone.', 30),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Why do larger organisms need exchange surfaces and transport systems?', 'They have a smaller surface area to volume ratio and longer diffusion distances, so diffusion alone is too slow.', 1),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Calculate the SA:V ratio of a 2 cm cube.', 'SA = 6 × 2² = 24 cm²; volume = 2³ = 8 cm³; ratio = 24 : 8 = 3 : 1.', 2),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'What substances must be transported into and out of the body?', 'In: oxygen, nutrients, water. Out: carbon dioxide and urea.', 3),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'How are alveoli adapted for gas exchange?', 'Large surface area, walls one cell thick (short diffusion distance), rich capillary network and ventilation maintain a steep concentration gradient.', 4),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'State Fick''s law.', '(Biology only) Rate of diffusion ∝ (surface area × concentration difference) ÷ thickness of membrane.', 5),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'List the components of blood and their roles.', 'Red blood cells carry oxygen; white blood cells fight pathogens; platelets clot blood; plasma transports dissolved CO₂, glucose, urea, hormones.', 6),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'How are red blood cells adapted?', 'Biconcave shape for large surface area, no nucleus so more room for haemoglobin, which binds oxygen.', 7),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Name two types of white blood cell and their roles.', 'Phagocytes engulf and digest pathogens; lymphocytes produce antibodies.', 8),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Describe the structure of arteries.', 'Thick muscular and elastic walls and small lumen to withstand and maintain high pressure from the heart.', 9),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Describe the structure of veins.', 'Thin walls, large lumen, valves to prevent backflow of low-pressure blood returning to the heart.', 10),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'How are capillaries adapted?', 'Walls one cell thick for short diffusion distance; narrow and highly branched for a large surface area.', 11),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Trace blood through the heart.', 'Vena cava, right atrium, right ventricle, pulmonary artery, lungs, pulmonary vein, left atrium, left ventricle, aorta.', 12),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Why is the left ventricle wall thicker than the right?', 'It pumps blood at higher pressure around the whole body, whereas the right pumps only to the lungs.', 13),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Why is the human circulatory system called a double system?', 'Blood passes through the heart twice per circuit: once to the lungs and once to the body.', 14),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'What is the function of valves in the heart?', 'Prevent backflow of blood, ensuring it flows in one direction.', 15),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'State the equation for cardiac output.', 'Cardiac output = stroke volume × heart rate.', 16),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Heart rate 70 bpm, stroke volume 75 cm³. Cardiac output?', '75 × 70 = 5250 cm³ per minute (5.25 dm³/min).', 17),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Cardiac output is 6000 cm³/min and heart rate is 80 bpm. Find stroke volume.', 'Stroke volume = 6000 ÷ 80 = 75 cm³.', 18),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'State the word and symbol equation for aerobic respiration.', 'Glucose + oxygen → carbon dioxide + water. C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O.', 19),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'State the equation for anaerobic respiration in muscles.', 'Glucose → lactic acid.', 20),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'State the equation for anaerobic respiration in yeast and plants.', 'Glucose → ethanol + carbon dioxide (fermentation).', 21),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Compare aerobic and anaerobic respiration.', 'Aerobic needs oxygen, releases much more energy, products CO₂ and water. Anaerobic needs no oxygen, releases less energy, incomplete breakdown of glucose.', 22),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'What is an oxygen debt?', 'Extra oxygen needed after exercise to break down lactic acid that built up during anaerobic respiration.', 23),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Why is respiration exothermic?', 'It transfers energy to the environment; it is a continuous process in all living cells.', 24),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Give uses of energy from respiration.', 'Muscle contraction, building larger molecules (e.g. proteins), active transport, maintaining body temperature in mammals and birds.', 25),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Core practical: how does a respirometer measure respiration rate?', 'Organisms (e.g. woodlice or seeds) in a sealed tube with soda lime to absorb CO₂; oxygen uptake moves coloured liquid along a capillary; distance per minute.', 26),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Core practical: why is soda lime used and what is the control?', 'Soda lime absorbs CO₂ so liquid movement shows only oxygen use. Control: same tube with glass beads of equal volume instead of organisms.', 27),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Core practical: how is temperature varied in the respirometer practical?', 'Place tubes in water baths at different temperatures, leave to equilibrate, then measure distance moved by liquid in a set time.', 28),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'A liquid moves 18 mm in 6 minutes. What is the rate of respiration?', '18 ÷ 6 = 3 mm per minute (of oxygen consumption).', 29),
  ('Biology', 'Edexcel', 'gcse', '8', 'Exchange & Transport in Animals', 'Exam trap: do plants respire only at night?', 'No. Plants respire all the time; in light, photosynthesis may exceed respiration so net gas exchange is CO₂ uptake.', 30),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Define population, community and ecosystem.', 'Population: all organisms of one species in an area. Community: populations of different species. Ecosystem: community plus abiotic factors interacting.', 1),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Give examples of abiotic factors.', 'Light intensity, temperature, water availability, pollutants, CO₂ and oxygen levels, soil pH and minerals.', 2),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Give examples of biotic factors.', 'Competition, predation, disease, food availability.', 3),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'What do animals and plants compete for?', 'Animals: food, mates, territory, water. Plants: light, water, space, mineral ions.', 4),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Define interdependence.', 'The way species in a community depend on each other for food, shelter, pollination, seed dispersal; a change in one affects others.', 5),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Define parasitism and mutualism.', 'Parasitism: parasite benefits, host harmed (e.g. tapeworm, fleas). Mutualism: both benefit (e.g. oxpeckers on buffalo, nitrogen-fixing bacteria in legumes).', 6),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Explain predator–prey cycles.', 'Prey increase, so predators increase; more predators eat more prey, so prey fall; predators then fall. Predator peaks lag behind prey peaks.', 7),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Core practical: how do you estimate population size with quadrats?', 'Place quadrats randomly (random coordinates), count organisms in each, find mean per quadrat, then multiply up to total area.', 8),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Mean 4 daisies per 0.25 m² quadrat; field is 100 m². Estimate population.', '4 ÷ 0.25 = 16 per m²; 16 × 100 = 1600 daisies.', 9),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Core practical: when and how is a belt transect used?', 'To study how distribution changes across a gradient (e.g. from shade to light); place quadrats at regular intervals along a tape and measure abiotic factors too.', 10),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Why must quadrats be placed randomly?', 'To avoid bias and get a representative sample; a larger number of quadrats improves reliability.', 11),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Why does energy decrease along a food chain?', 'Energy is lost through respiration (heat), movement, excretion and undigested material in faeces, so only about 10% is transferred.', 12),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Calculate efficiency of energy transfer if 2000 kJ goes to 150 kJ.', '(Biology only) Efficiency = energy transferred ÷ energy available × 100 = 150 ÷ 2000 × 100 = 7.5%.', 13),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Why is a pyramid of biomass usually more useful than a pyramid of numbers?', 'It always has a pyramid shape and shows the mass of living material at each level, whereas numbers ignore organism size.', 14),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Define biodiversity.', 'The variety of different species of organisms on Earth or within an ecosystem.', 15),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'What is eutrophication?', 'Fertiliser runoff adds nitrates/phosphates to water; algae grow and block light; plants die; bacteria decompose them using oxygen; fish and other organisms die.', 16),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'How can fish farming affect biodiversity?', 'Waste and food cause eutrophication; diseases and parasites spread to wild fish; escaped fish compete with or breed with wild populations.', 17),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'How do non-indigenous species affect ecosystems?', 'They may outcompete native species for resources, carry disease, or lack natural predators (e.g. grey squirrels vs red squirrels).', 18),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'How do conservation and reforestation increase biodiversity?', 'Protect habitats and endangered species, breeding programmes; replanting trees restores habitats and food sources for many species.', 19),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Describe the carbon cycle.', 'Photosynthesis removes CO₂; respiration by organisms and decomposers and combustion release CO₂; carbon passes along food chains by feeding; some forms fossil fuels.', 20),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'What role do decomposers play in material cycles?', 'Bacteria and fungi break down dead matter and waste, releasing CO₂ by respiration and returning mineral ions to the soil.', 21),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Describe the water cycle.', 'Evaporation and transpiration, condensation forming clouds, precipitation, run-off and percolation back to rivers and seas.', 22),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'How is potable water produced in areas of drought?', 'Desalination by distillation or reverse osmosis to remove salt from seawater.', 23),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Describe the nitrogen cycle.', 'Nitrogen-fixing bacteria convert N₂ to ammonia/nitrates; decomposers turn proteins into ammonia; nitrifying bacteria convert ammonia to nitrates; denitrifying bacteria return N₂ to air.', 24),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'How do farmers increase soil nitrates?', 'Crop rotation with legumes (nitrogen-fixing bacteria in root nodules), adding manure or chemical fertilisers.', 25),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'What are indicator species?', '(Biology only) Species whose presence or absence shows pollution levels, e.g. lichens (air quality, SO₂), bloodworms and sludgeworms (polluted water), stonefly larvae (clean water).', 26),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Practical: how is temperature''s effect on decomposition investigated?', '(Biology only) Milk, lipase and phenolphthalein/sodium carbonate in water baths; time for pink to disappear as fatty acids lower pH; repeat at different temperatures.', 27),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'What factors affect the rate of decay?', '(Biology only) Temperature, water content and oxygen availability; warm, moist, aerobic conditions speed up decomposition.', 28),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Calculate rate of decay if 120 g of compost loses 30 g in 10 days.', '(Biology only) Rate = mass lost ÷ time = 30 ÷ 10 = 3 g per day.', 29),
  ('Biology', 'Edexcel', 'gcse', '9', 'Ecosystems & Material Cycles', 'Give biological factors affecting food security.', '(Biology only) Rising population, changing diets, new pests and pathogens, environmental change, cost of agricultural inputs, conflict.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Biology' AND exam_board = 'Edexcel' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
